export { default as Message } from "./Message.vue";
export { default as MessageAvatar } from "./MessageAvatar.vue";
export { default as MessageContent } from "./MessageContent.vue";
export { default as MessageFooter } from "./MessageFooter.vue";
export { default as MessageGroup } from "./MessageGroup.vue";
export { default as MessageHeader } from "./MessageHeader.vue";
export type * from "./types.ts";

@layer components {
  /* Message */

  [data-slot="message-group"] {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    min-width: 0;
  }

  [data-slot="message"][data-align] {
    display: flex;
    font-size: 0.875rem;
    gap: 0.5rem;
    line-height: 1.25rem;
    min-width: 0;
    position: relative;
    width: 100%;
  }

  [data-slot="message"][data-align="end"] {
    flex-direction: row-reverse;
  }

  [data-slot="message-avatar"] {
    align-items: center;
    align-self: flex-end;
    background: var(--vh-bg-elevated);
    border-radius: 9999px;
    display: flex;
    flex-shrink: 0;
    justify-content: center;
    min-width: 2rem;
    overflow: hidden;
    width: fit-content;
  }

  [data-slot="message"][data-align]:has([data-slot="message-footer"]) [data-slot="message-avatar"] {
    translate: 0 -2rem;
  }

  [data-slot="message-content"] {
    display: flex;
    flex-direction: column;
    gap: 0.625rem;
    min-width: 0;
    overflow-wrap: break-word;
    width: 100%;
  }

  [data-slot="message"][data-align="end"] [data-slot="message-content"] > [data-slot] {
    align-self: flex-end;
  }

  :is([data-slot="message-header"], [data-slot="message-footer"]) {
    align-items: center;
    color: var(--vh-muted);
    display: flex;
    font-size: 0.75rem;
    font-weight: 500;
    line-height: 1rem;
    max-width: 100%;
    min-width: 0;
    padding-inline: 0.75rem;
  }

  /* Without a framed bubble, the header and footer line up with the unframed content. */
  [data-slot="message"][data-align]:is(:has([data-variant="ghost"]), :not(:has([data-slot="bubble"]))) :is([data-slot="message-header"], [data-slot="message-footer"]) {
    padding-inline: 0;
  }

  [data-slot="message"][data-align="end"] [data-slot="message-footer"] {
    justify-content: flex-end;
  }
}

export type MessageAlign = "start" | "end";

export interface MessageProps {
  /** The side the message speaks from. A reply from the viewer uses `end`. */
  align?: MessageAlign;
}

export interface MessageSlots {
  /** The parts of the message: `MessageAvatar` and `MessageContent`, with `MessageHeader` and `MessageFooter` in it. */
  default?: () => unknown;
}
